fn locale_to_lang(code: &str) -> Option<&'static str> {
    Some(match code {
        "nb" | "nn" | "no" => "nor",
        "en" => "eng",
        "nl" => "nld",
        "fr" => "fra",
        "es" => "spa",
        "de" => "deu",
        "sv" => "swe",
        "da" => "dan",
        "it" => "ita",
        _ => return None,
    })
}

/// Pick a UI language from the system locale, defaulting to English.
pub fn current_lang() -> &'static str {
    for var in ["LC_ALL", "LC_MESSAGES", "LANG", "LANGUAGE"] {
        if let Ok(v) = std::env::var(var) {
            if !v.is_empty() {
                let code = v
                    .split(':')
                    .next()
                    .unwrap_or("")
                    .split('.')
                    .next()
                    .unwrap_or("")
                    .split('_')
                    .next()
                    .unwrap_or("")
                    .to_lowercase();
                if let Some(l) = locale_to_lang(&code) {
                    return l;
                }
            }
        }
    }
    "eng"
}
